/* go-perl native XS SDK: the internals of perl that go-perl does not give
 * native code. GENERATED by .work gen_internals.py; the list is the one
 * place to change.
 *
 * Native code here runs in another memory than the interpreter's, and is
 * given the interpreter through the perl API: its values, its handles, its
 * subs. What perl keeps for itself is not handed over: the save stack,
 * the stacks of contexts and of stack infos, the op tree's roots and the
 * regexp of a match op, the bodies of SVs, the SV arenas, the jump
 * environment, the directory stream of a dirhandle, the layers of PerlIO
 * handles. A module that uses one of these names stops building, with a
 * message that says which and why: one fixed phrase ("go-perl gives native code no access to this interpreter internal")
 * and the name. The use is what fails, not the header: #ifdef sees the
 * name defined, and a module that never uses it builds.
 *
 * Members of structures (si_stack, op_pmreplrootu, cop_hints_hash, ...)
 * cannot be caught this way; using one stays a compiler error of its own
 * ("has no member named"). */
#ifndef GOPERL_XS_SDK_INTERNALS_H
#define GOPERL_XS_SDK_INTERNALS_H
#pragma GCC system_header

#define GOPERL_NO_INTERNAL_PRAGMA(x) _Pragma(#x)

/* the pads and the context and stackinfo stacks */
#undef pad_push
#define pad_push GOPERL_NO_INTERNAL_PRAGMA(GCC error "go-perl gives native code no access to this interpreter internal: pad_push") 0
#undef Perl_pad_push
#define Perl_pad_push GOPERL_NO_INTERNAL_PRAGMA(GCC error "go-perl gives native code no access to this interpreter internal: Perl_pad_push") 0
#undef new_stackinfo
#define new_stackinfo GOPERL_NO_INTERNAL_PRAGMA(GCC error "go-perl gives native code no access to this interpreter internal: new_stackinfo") 0
#undef Perl_new_stackinfo
#define Perl_new_stackinfo GOPERL_NO_INTERNAL_PRAGMA(GCC error "go-perl gives native code no access to this interpreter internal: Perl_new_stackinfo") 0
#undef new_stackinfo_flags
#define new_stackinfo_flags GOPERL_NO_INTERNAL_PRAGMA(GCC error "go-perl gives native code no access to this interpreter internal: new_stackinfo_flags") 0
#undef Perl_new_stackinfo_flags
#define Perl_new_stackinfo_flags GOPERL_NO_INTERNAL_PRAGMA(GCC error "go-perl gives native code no access to this interpreter internal: Perl_new_stackinfo_flags") 0
#undef SWITCHSTACK
#define SWITCHSTACK GOPERL_NO_INTERNAL_PRAGMA(GCC error "go-perl gives native code no access to this interpreter internal: SWITCHSTACK") 0

/* the SV arenas: PL_sv_arenaroot is the interpreter's first arena (perl.h) */
#undef PL_sv_root
#define PL_sv_root GOPERL_NO_INTERNAL_PRAGMA(GCC error "go-perl gives native code no access to this interpreter internal: PL_sv_root") 0

/* the directory stream of a dirhandle */
#undef IoDIRP
#define IoDIRP GOPERL_NO_INTERNAL_PRAGMA(GCC error "go-perl gives native code no access to this interpreter internal: IoDIRP") 0

#endif /* GOPERL_XS_SDK_INTERNALS_H */
